func(s *Server)ingest(w http.ResponseWriter,r *http.Request){key:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer ");var project,keyID string;e:=s.DB.QueryRow(r.Context(),"SELECT project_id,id FROM api_keys WHERE key_hash=$1 AND revoked_at IS NULL",security.Hash(key)).Scan(&project,&keyID);if errors.Is(e,pgx.ErrNoRows){fail(w,r,401,"UNAUTHORIZED","valid API key required");return};if e!=nil{s.dbError(w,r,e);return};allowed,e:=redisx.Allow(r.Context(),s.Redis,"ingest:"+keyID,50,100);if e!=nil{fail(w,r,503,"UNAVAILABLE","rate limiter unavailable; retry later");return};if !allowed{w.Header().Set("Retry-After","1");fail(w,r,429,"RATE_LIMITED","ingestion rate exceeded");return};var v events.Input;if !decode(w,r,&v){return};if e=v.Validate();e!=nil{fail(w,r,400,"INVALID_EVENT",e.Error());return};payload,hash,e:=v.Canonical();if e!=nil{fail(w,r,400,"INVALID_EVENT","invalid payload");return};tx,e:=s.DB.Begin(r.Context());if e!=nil{s.dbError(w,r,e);return};defer tx.Rollback(r.Context());id:=security.Token("evt_");tag,e:=tx.Exec(r.Context(),"INSERT INTO events(id,project_id,event_id,type,payload,payload_hash) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(project_id,event_id) DO NOTHING",id,project,v.EventID,v.Type,payload,hash);if e!=nil{s.dbError(w,r,e);return};if tag.RowsAffected()==0{var oldHash string;e=tx.QueryRow(r.Context(),"SELECT id,payload_hash FROM events WHERE project_id=$1 AND event_id=$2",project,v.EventID).Scan(&id,&oldHash);if e!=nil{s.dbError(w,r,e);return};if oldHash!=hash{fail(w,r,409,"IDEMPOTENCY_CONFLICT","event_id already exists with different content");return};write(w,200,map[string]any{"id":id,"duplicate":true});return};_,e=tx.Exec(r.Context(),"INSERT INTO deliveries(id,event_id,endpoint_id) SELECT 'dlv_' || md5($1 || ':' || id),$1,id FROM endpoints WHERE project_id=$2 AND active AND deleted_at IS NULL",id,project);if e!=nil{s.dbError(w,r,e);return};if e=tx.Commit(r.Context());e!=nil{s.dbError(w,r,e);return};s.Log.Info("event accepted","request_id",r.Context().Value(requestKey),"event_id",id,"project_id",project);write(w,202,map[string]any{"id":id,"duplicate":false})}
